CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','manager') NOT NULL,store_id BIGINT UNSIGNED NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,description TEXT NULL,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stores(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,code VARCHAR(30) NOT NULL UNIQUE,address VARCHAR(255),status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sku VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,category_id BIGINT UNSIGNED NULL,description TEXT,unit_price DECIMAL(12,2) NOT NULL DEFAULT 0,cost_price DECIMAL(12,2) NOT NULL DEFAULT 0,reorder_level INT NOT NULL DEFAULT 10,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS suppliers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,email VARCHAR(190),phone VARCHAR(40),address VARCHAR(255),status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stock(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,store_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity INT NOT NULL DEFAULT 0,reserved INT NOT NULL DEFAULT 0,UNIQUE KEY uq_stock(store_id,product_id));
CREATE TABLE IF NOT EXISTS stock_movements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,store_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,type ENUM('in','out','adjustment','opening') NOT NULL,quantity INT NOT NULL,reason VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS purchases(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,store_id BIGINT UNSIGNED NOT NULL,supplier_id BIGINT UNSIGNED NULL,requested_by BIGINT UNSIGNED NULL,status ENUM('requested','approved','received','rejected','cancelled') DEFAULT 'requested',total DECIMAL(12,2) DEFAULT 0,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS purchase_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,purchase_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity INT NOT NULL,unit_cost DECIMAL(12,2) NOT NULL);
CREATE TABLE IF NOT EXISTS orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,store_id BIGINT UNSIGNED NOT NULL,customer_name VARCHAR(160),customer_email VARCHAR(190),status ENUM('pending','processing','ready','completed','cancelled') DEFAULT 'pending',total DECIMAL(12,2) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(12,2) NOT NULL);
CREATE TABLE IF NOT EXISTS returns(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NULL,store_id BIGINT UNSIGNED NOT NULL,customer_name VARCHAR(160),type ENUM('return','exchange') DEFAULT 'return',status ENUM('requested','approved','rejected','refunded','completed') DEFAULT 'requested',refund_amount DECIMAL(12,2) DEFAULT 0,reason TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(120) NOT NULL,entity VARCHAR(80),entity_id BIGINT UNSIGNED NULL,details TEXT,ip_address VARCHAR(64),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS login_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,email VARCHAR(190),success TINYINT(1) NOT NULL,ip_address VARCHAR(64),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,title VARCHAR(180),message TEXT,is_read TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings(id INT PRIMARY KEY,site_name VARCHAR(160),currency VARCHAR(10),low_stock_alert TINYINT(1) DEFAULT 1,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
